--
-- Disparadores `proyecto_gestionado`
--
DELIMITER $$
CREATE TRIGGER `trg_after_insert_proyecto_gestionado` AFTER INSERT ON `proyecto_gestionado` FOR EACH ROW BEGIN
    DECLARE v_id_pm INT;

    -- 1️⃣ Inserción automática en pm_calidad
    INSERT INTO pm_calidad (
        id_proyecto_gestionado,
        horas_pm,
        usu_crea,
        estados_id,
        fech_crea
    )
    VALUES (
        NEW.id,       -- ID recién insertado del proyecto
        NULL,         -- horas_pm iniciales (pueden actualizarse luego)
        NEW.usu_crea, -- mismo usuario que creó el proyecto
        1,            -- estado inicial (activo)
        NOW()         -- fecha de creación
    );

    -- 2️⃣ Obtener el ID recién creado en pm_calidad
    SET v_id_pm = LAST_INSERT_ID();

    -- 3️⃣ Inserción automática en timesummary_estados (vinculando al PM)
    INSERT INTO timesummary_estados (
        id_pm_calidad,
        usuario_asignado,
        id_proyecto_gestionado,
        fecha_creacion,
        est
    )
    VALUES (
        v_id_pm,      -- referencia al registro en pm_calidad
        NEW.usu_crea, -- el usuario creador del proyecto (PM)
        NEW.id,       -- ID del nuevo proyecto
        NOW(),        -- fecha actual
        1             -- estado activo
    );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_after_insert_proyecto_gestionado_insert_hosts_recurrentes` AFTER INSERT ON `proyecto_gestionado` FOR EACH ROW BEGIN
    -- Inserta en hosts usando el id recién generado
    INSERT INTO hosts (
        id_proyecto_gestionado,
        id_proyecto_cantidad_servicios,
        usu_crea,
        tipo,
        host,
        fecha_carga,
        est
    )
    SELECT 
        NEW.id,                       -- usar el id recién insertado
        NEW.id_proyecto_cantidad_servicios,
        NEW.usu_crea,
        h.tipo,
        h.host,
        NOW(),
        1                             -- siempre est = 1
    FROM hosts h
    WHERE h.id_proyecto_cantidad_servicios = NEW.id_proyecto_cantidad_servicios
      AND h.id_proyecto_gestionado = (
          SELECT MIN(id_proyecto_gestionado)
          FROM hosts
          WHERE id_proyecto_cantidad_servicios = NEW.id_proyecto_cantidad_servicios
      );
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_update_pm_calidad` AFTER UPDATE ON `proyecto_gestionado` FOR EACH ROW BEGIN
    -- Solo si el registro sigue activo (est=1)
    IF NEW.est = 1 THEN
        UPDATE pm_calidad
        SET 
            horas_pm = (
                SELECT hs_dimensionadas
                FROM dimensionamiento
                WHERE id_proyecto_gestionado = NEW.id
                LIMIT 1
            ),
            usu_crea = NEW.usu_crea,
            fech_crea = NOW()
        WHERE id_proyecto_gestionado = NEW.id;
    END IF;
END
$$
DELIMITER ;

